CREATE TABLE "C##GIS_USER"."RETAIL_STORES"
  (
    "STORE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1
    START WITH 1 CACHE 20 NOORDER NOCYCLE NOT NULL ENABLE,
    "CHAIN_ID"   NUMBER NOT NULL ENABLE,
    "STORE_NUM"  VARCHAR2(20 BYTE),
    "STORE_NAME" VARCHAR2(150 BYTE),
    "BRAND"      VARCHAR2(4000 BYTE),
    "STORE_TYPE" VARCHAR2(6 BYTE),
    "GEOM" "SDO_GEOMETRY",
    "LEGAL_DETAILS"        VARCHAR2(250 BYTE),
    "TIN"                  VARCHAR2(20 BYTE) NOT NULL ENABLE,
    "HOUSE_NUMBER"         VARCHAR2(20 BYTE),
    "STREET"               VARCHAR2(255 BYTE),
    "CITY"                 VARCHAR2(50 BYTE),
    "STATE"                CHAR(2 BYTE),
    "COUNTRY"              VARCHAR2(60 BYTE),
    "POSTAL_CODE"          VARCHAR2(15 BYTE),
    "ZIP_CODE"             VARCHAR2(20 BYTE),
    "PHONE"                VARCHAR2(15 BYTE),
    "EMAIL"                VARCHAR2(255 BYTE),
    "SITE"                 VARCHAR2(4000 BYTE),
    "SOCIAL_MEDIA"         VARCHAR2(4000 BYTE),
    "OPERATING_HOURS"      DATE,
    "TOTAL_AREA"           NUMBER,
    "RETAIL_SPACE"         NUMBER,
    "NUMBER_FLOORS"        NUMBER,
    "PARKING_AVAILABLE"    CHAR(1 BYTE),
    "RETAIL_AREAS"         VARCHAR2(255 BYTE),
    "HIERARCHY_CATEGORIES" VARCHAR2(255 BYTE),
    "MANUFACTURERS"        VARCHAR2(255 BYTE),
    "STAFF"                VARCHAR2(255 BYTE),
    "SUPPLIERS"            VARCHAR2(255 BYTE),
    "TENANTS"              VARCHAR2(255 BYTE),
    "PROMOTIONS"           VARCHAR2(255 BYTE),
    "DISCOUNTS"            NUMBER,
    PRIMARY KEY ("STORE_ID") USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT) TABLESPACE "USERS" ENABLE,
    CONSTRAINT "FK_STORE_CHAIN" FOREIGN KEY ("CHAIN_ID") REFERENCES "C##GIS_USER"."RETAIL_CHAINS" ("CHAIN_ID") ENABLE
  )
  SEGMENT CREATION IMMEDIATE PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 NOCOMPRESS LOGGING STORAGE
  (
    INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT
  )
  TABLESPACE "USERS" VARRAY "GEOM"."SDO_ELEM_INFO" STORE AS SECUREFILE LOB
  (
    TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192 CACHE NOCOMPRESS KEEP_DUPLICATES STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  )
  VARRAY "GEOM"."SDO_ORDINATES" STORE AS SECUREFILE LOB
  (
    TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192 CACHE NOCOMPRESS KEEP_DUPLICATES STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645 PCTINCREASE 0 BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  ) ;